{"code":"import pandas as pd, statsmodels.api as sm
x=pd.read_csv('data/explore.csv'); cols=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for c in cols:
